import { BadgeComponent } from '../../../../packages/components/ui';
import { Component, ChangeDetectionStrategy, input, computed } from '@angular/core';

@Component({
  selector: 'app-status-cell',
  standalone: true,
  template: `
    <ui-badge [variant]="badgeVariant()">
      {{ status() }}
    </ui-badge>
  `,
  imports: [BadgeComponent],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class StatusCellComponent {
  status = input.required<string>();

  badgeVariant = computed(() => {
    const s = this.status();
    if (s === 'success') return 'default';
    if (s === 'processing') return 'secondary';
    if (s === 'pending') return 'outline';
    return 'destructive';
  });
}

import { Component, ChangeDetectionStrategy, output } from '@angular/core';
import { InputComponent } from '../../../../packages/components/ui';

@Component({
  selector: 'app-text-filter',
  standalone: true,
  template: `
    <ui-input
      type="text"
      placeholder="Filter..."
      class="h-8 w-full"
      (input)="onInputChange($event)"
    />
  `,
  imports: [InputComponent],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TextFilterComponent {
  filterChange = output<string>();

  onInputChange(event: Event) {
    const value = (event.target as HTMLInputElement).value;
    this.filterChange.emit(value);
  }
}

